#!/usr/bin/env python3
"""Synchronize AmapAds.conf -> Surge, preserving Polly-ai metadata.

Run at the repository root. No third-party Python dependencies are needed.
Unknown upstream syntax, missing MITM hosts, download failures and invalid JS
abort before changing files. Scripts retain the upstream authors' notices.
A stable source hash replaces wall-clock timestamps to avoid daily no-op commits.
"""
from __future__ import annotations

import argparse
import hashlib
import re
import subprocess
import sys
import urllib.request
from pathlib import Path
from urllib.parse import urlparse

UPSTREAM_URL = "https://raw.githubusercontent.com/ddgksf2013/Rewrite/master/AdBlock/AmapAds.conf"
MODULE_PATH = Path("Surge/Module/AmapAds.sgmodule")
ASSET_PATH = Path("Surge/JavaScript/Amap")
RAW_ROOT = "https://raw.githubusercontent.com/Polly-ai/Wynston/main"
CATEGORY = "Polly-ai"
HOST_RULES = {"host": "DOMAIN", "host-suffix": "DOMAIN-SUFFIX",
              "host-keyword": "DOMAIN-KEYWORD", "host-wildcard": "DOMAIN-WILDCARD",
              "ip-cidr": "IP-CIDR", "ip6-cidr": "IP-CIDR6"}
# Surge's documented URL Rewrite action is plain "reject" only.
# Preserve QX's successful mock responses with a small http-request adapter.
REPLY_ACTIONS = {"reject-200": "empty", "reject-dict": "dict",
                 "reject-array": "array", "reject-img": "image"}
REPLY_JS = '''// Surge adapter for Quantumult X mock responses; upstream rules: @ddgksf2013.
// Generated by .github/scripts/sync_amap.py. Never sends these requests upstream.
const mode = typeof $argument === "string" ? $argument : "empty";
const response = {status: 200, headers: {"Cache-Control": "no-store"}, body: ""};
if (mode === "dict" || mode === "array") {
  response.headers["Content-Type"] = "application/json; charset=utf-8";
  response.body = mode === "dict" ? "{}" : "[]";
} else if (mode === "image") {
  response.headers["Content-Type"] = "image/gif";
  // Transparent 1x1 GIF89a. The module enables binary-body-mode for image rules.
  response.body = new Uint8Array([71,73,70,56,57,97,1,0,1,0,128,0,0,0,0,0,
    255,255,255,33,249,4,1,0,0,0,0,44,0,0,0,0,1,0,1,0,0,2,1,68,0,59]);
} else if (mode === "empty") {
  response.headers["Content-Type"] = "text/plain; charset=utf-8";
} else {
  throw new Error("Unsupported Amap response mode");
}
$done({response: response});
'''


class SyncError(ValueError):
    pass


def download(url: str) -> str:
    """Verified HTTPS only. Do not overwrite anything on fetch/decode errors."""
    if urlparse(url).scheme != "https":
        raise SyncError(f"Refusing a non-HTTPS source: {url}")
    error = None
    for _ in range(3):
        try:
            request = urllib.request.Request(url, headers={
                "User-Agent": "Wynston-Amap-Sync/1.0", "Cache-Control": "no-cache"})
            with urllib.request.urlopen(request, timeout=45) as response:
                if response.status != 200:
                    raise SyncError(f"HTTP {response.status}: {url}")
                data = response.read(2_000_001)
                if len(data) > 2_000_000:
                    raise SyncError(f"Source unexpectedly exceeds 2 MB: {url}")
                text = data.decode("utf-8-sig")
                if not text.strip() or text.lstrip().lower().startswith("<!doctype html"):
                    raise SyncError(f"Empty or HTML source: {url}")
                return text
        except Exception as exc:
            error = exc
    raise SyncError(f"Download failed for {url}: {error}")


def logical_lines(text: str):
    """Accept upstream comments and explicitly wrapped host/script lines."""
    pending = ""
    pending_comment = ""
    comment = ""
    for number, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line:
            continue
        if line.startswith(("#", "//", ";")):
            if line.startswith("# >"):
                comment = line
            continue
        if pending:
            line = pending + " " + line
            comment = pending_comment
            pending = ""
        if ((line.startswith("hostname") and line.endswith(","))
                or re.search(r"\burl\s+script-(?:response|request)-body$", line)):
            pending, pending_comment = line, comment
            continue
        yield number, line, comment
        comment = ""
    if pending:
        raise SyncError("Incomplete upstream continuation line")


def metadata(text: str, key: str, default: str = "") -> str:
    match = re.search(r"^\s*//\s*@" + re.escape(key) + r"\s+(.+?)\s*$", text, re.M)
    return match.group(1) if match else default


def module_comment(comment: str) -> str:
    """Remove only the requested attribution token from rendered module comments."""
    return comment.replace("@ddgksf2013", "")


def convert(text: str) -> tuple[str, dict[str, str]]:
    """Return module text and {upstream script URL: local basename}."""
    rules, rewrites, scripts, hosts = [], [], [], []
    assets = {}
    basenames = {}
    seen = set()
    for number, line, comment in logical_lines(text):
        host_match = re.fullmatch(r"hostname\s*=\s*(.+)", line)
        if host_match:
            for host in host_match.group(1).split(","):
                host = host.strip()
                if not re.fullmatch(r"[A-Za-z0-9*_.-]+", host):
                    raise SyncError(f"Line {number}: invalid MITM hostname {host!r}")
                if host not in hosts:
                    hosts.append(host)
            continue
        route_match = re.fullmatch(r"([\w-]+)\s*,\s*([^,]+)\s*,\s*(direct|reject)", line, re.I)
        if route_match and route_match.group(1).lower() in HOST_RULES:
            qx_type, value, action = route_match.groups()
            surge_type = HOST_RULES[qx_type.lower()]
            result = f"{surge_type},{value.strip()},{action.upper()}"
            if surge_type in ("IP-CIDR", "IP-CIDR6"):
                result += ",no-resolve"
            if comment:
                rules.append(module_comment(comment))
            rules.append(result)
            continue
        match = re.fullmatch(r"(\^\S+)\s+url\s+(\S+)(?:\s+(https://\S+))?", line)
        if not match:
            raise SyncError(f"Line {number}: unsupported upstream syntax: {line!r}")
        pattern, action, source = match.groups()
        if pattern in seen:
            raise SyncError(f"Line {number}: duplicate URL pattern")
        seen.add(pattern)
        try:
            re.compile(pattern)
        except re.error as exc:
            raise SyncError(f"Line {number}: invalid URL regex: {exc}") from exc
        if "," in pattern:
            raise SyncError(f"Line {number}: comma in URL regex requires manual review")
        suffix = hashlib.sha256(pattern.encode()).hexdigest()[:12]
        target = rewrites if action == "reject" else scripts
        if comment:
            target.append(module_comment(comment))
        if action == "reject" and source is None:
            rewrites.append(f"{pattern} _ reject")
        elif action in REPLY_ACTIONS and source is None:
            mode = REPLY_ACTIONS[action]
            binary = "binary-body-mode=true, " if mode == "image" else ""
            scripts.append(f"amap_reply_{suffix} = type=http-request, pattern={pattern}, "
                           f"requires-body=false, {binary}"
                           f"script-path={RAW_ROOT}/{ASSET_PATH.as_posix()}/amap-reply.js, "
                           f"argument={mode}, timeout=5")
        elif action in ("script-response-body", "script-request-body") and source:
            parsed = urlparse(source)
            if (parsed.netloc != "raw.githubusercontent.com" or parsed.query or parsed.fragment
                    or not parsed.path.startswith("/ddgksf2013/Scripts/")):
                raise SyncError(f"Line {number}: unexpected script source needs review: {source}")
            basename = Path(parsed.path).name
            if not re.fullmatch(r"[A-Za-z0-9_-]+\.js", basename) or basename == "amap-reply.js":
                raise SyncError(f"Line {number}: unsafe/reserved script basename")
            if basename in basenames and basenames[basename] != source:
                raise SyncError(f"Line {number}: script basename collision")
            assets[source] = basename
            basenames[basename] = source
            script_type = "http-response" if action == "script-response-body" else "http-request"
            scripts.append(f"amap_body_{suffix} = type={script_type}, pattern={pattern}, "
                           f"requires-body=true, max-size=1048576, "
                           f"script-path={RAW_ROOT}/{ASSET_PATH.as_posix()}/{basename}, timeout=10")
        else:
            raise SyncError(f"Line {number}: unsupported action: {action!r}")
    if not hosts or not assets or not seen:
        raise SyncError("Upstream must contain MITM hosts, script sources and URL rules")
    out = [
        "#!name = 高德地图净化",
        "#!desc = 高德地图去广告：开屏、首页信息流、搜索热词与推广；每日随上游自动更新。",
        f"#!category = {CATEGORY}",
        "#!author = ",
        f"# 上游来源：{UPSTREAM_URL}",
        f"# 上游版本：{metadata(text, 'Version', '未标注')}",
        f"# 原作者更新：{metadata(text, 'UpdateTime', '未标注')}",
        f"# 上游配置 SHA256：{hashlib.sha256(text.encode()).hexdigest()}",
        "# 转换与维护：Polly-ai/Wynston；保留原作者署名，JavaScript 按原样同步。",
        "# reject-200/reject-dict/reject-img 用 Surge 请求脚本保留 HTTP 200 空体/空对象/透明 GIF 语义。",
        "# 响应脚本最多缓存 1 MiB；超限时 Surge 透传，避免 iOS 内存过载。",
        "# 原作者提示：使用前请卸载高德地图，挂载脚本然后使用。",
        "# 使用须启用 MITM 并安装、信任其证书；不要与同类高德净化模块重复启用。",
    ]
    for name, entries in (("Rule", rules), ("URL Rewrite", rewrites), ("Script", scripts)):
        if entries:
            out.extend(["", f"[{name}]", *entries])
    out.extend(["", "[MITM]", "hostname = %APPEND% " + ", ".join(hosts), ""])
    return "\n".join(out), assets


def validate_js(sources: dict[str, str]):
    """Parse and smoke-test scripts in a Surge-like, no-network Node VM."""
    import tempfile
    with tempfile.TemporaryDirectory(prefix="amap-sync-") as directory:
        for filename, text in sources.items():
            if not text.strip() or "$done" not in text:
                raise SyncError(f"Invalid or empty JavaScript: {filename}")
            path = Path(directory) / filename
            path.write_text(text, encoding="utf-8")
            check = subprocess.run(["node", "--check", str(path)],
                                   capture_output=True, text=True, timeout=15)
            if check.returncode:
                raise SyncError(f"Invalid JavaScript {filename}: {check.stderr[:1000]}")
        harness = r'''
const fs = require('fs');
const vm = require('vm');
const directory = process.argv[1];
function run(name, request, response, argument) {
  let result, calls = 0;
  const sandbox = {$request: request, $response: response, $argument: argument,
    $done: value => { result = value; calls++; },
    console: {log() {}, warn() {}, error() {}}};
  vm.runInNewContext(fs.readFileSync(directory + '/' + name, 'utf8'), sandbox,
    {timeout: 2000, contextCodeGeneration: {strings: false, wasm: false}});
  if (calls !== 1 || !result || typeof result !== 'object')
    throw new Error(name + ': expected exactly one $done object');
  return result;
}
const empty = run('amap-reply.js', {url: 'https://m5.amap.com/'}, undefined, 'empty');
if (empty.response.status !== 200 || empty.response.body !== '')
  throw new Error('reject-200 response changed');
for (const [mode, expected] of [['dict', '{}'], ['array', '[]']]) {
  const reply = run('amap-reply.js', {}, undefined, mode).response;
  if (reply.status !== 200 || reply.body !== expected ||
      !reply.headers['Content-Type'].startsWith('application/json'))
    throw new Error('Invalid JSON mock response: ' + mode);
}
const image = run('amap-reply.js', {}, undefined, 'image').response;
const gif = Buffer.from(image.body);
if (image.status !== 200 || image.headers['Content-Type'] !== 'image/gif' ||
    gif.subarray(0, 6).toString() !== 'GIF89a' ||
    gif.readUInt16LE(6) !== 1 || gif.readUInt16LE(8) !== 1 || gif[gif.length-1] !== 59)
  throw new Error('Invalid transparent 1x1 GIF response');
if (fs.existsSync(directory + '/amdc.js')) {
  const active = run('amdc.js', {url: 'http://amdc.m.taobao.com/',
    headers: {'User-Agent': 'AMap/15.00'}}, {body: 'original'});
  if (typeof active.body !== 'string') throw new Error('amdc: AMap response missing');
  const pass = run('amdc.js', {url: 'http://amdc.m.taobao.com/',
    headers: {'user-agent': 'Unrelated/1.0'}}, {body: 'original'});
  if (Object.keys(pass).length) throw new Error('amdc: unrelated UA should pass through');
}
if (fs.existsSync(directory + '/amap.js')) {
  const result = run('amap.js', {url: 'https://m5.amap.com/ws/message/notice/list',
    headers: {}}, {body: JSON.stringify({data: {noticeList: [{title: 'ad'}]}})});
  const body = JSON.parse(result.body);
  if (!Array.isArray(body.data.noticeList) || body.data.noticeList.length !== 0)
    throw new Error('amap: notice-list cleanup failed');
}
'''
        try:
            result = subprocess.run(["node", "-e", harness, directory],
                                    capture_output=True, text=True, timeout=30)
        except (FileNotFoundError, subprocess.TimeoutExpired) as exc:
            raise SyncError("Node.js is required for script validation") from exc
        if result.returncode:
            raise SyncError(f"Surge VM smoke test failed: {result.stderr[:1500]}")


def write_changed(path: Path, content: str) -> bool:
    """Atomically replace only changed files, after all inputs were validated."""
    if path.exists() and path.read_text(encoding="utf-8") == content:
        return False
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".sync-tmp")
    temporary.write_text(content, encoding="utf-8")
    temporary.replace(path)
    return True


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--from-file", type=Path, help="Use a local upstream config")
    parser.add_argument("--script-dir", type=Path, help="Read upstream JS locally for offline tests")
    parser.add_argument("--root", type=Path, default=Path("."), help="Repository root")
    args = parser.parse_args(argv)
    try:
        text = args.from_file.read_text(encoding="utf-8-sig") if args.from_file else download(UPSTREAM_URL)
        module, references = convert(text)
        sources = {filename: (args.script_dir.joinpath(filename).read_text(encoding="utf-8-sig")
                              if args.script_dir else download(url))
                   for url, filename in references.items()}
        sources["amap-reply.js"] = REPLY_JS
        validate_js(sources)
        changed = []
        for filename, content in sources.items():
            path = args.root / ASSET_PATH / filename
            if write_changed(path, content):
                changed.append(path.as_posix())
        path = args.root / MODULE_PATH
        if write_changed(path, module):
            changed.append(path.as_posix())
        print("sync_amap: " + ("updated " + ", ".join(changed) if changed else "no upstream changes"))
        return 0
    except (SyncError, OSError, subprocess.SubprocessError) as exc:
        print(f"sync_amap: error: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())
